"import Mathlib

def pre (n : Int) : Bool := decide (n ≥ 0)
def prog (n : Int) : Option Int := if ¬ pre n then none else some (Nat.factorial n.toNat : Int)

#eval Plausible.Testable.check (∀ n : Int, ¬ (n ≥ 0) → prog n = none) { maxFail := 1000 }
#eval Plausible.Testable.check (∀ n : Int, n > 0 → prog n = Option.map (fun r => n * r) (prog (n - 1))) { maxFail := 1000 }
"

